<?php
/**
 * Configuración General del Sistema
 * Cooperativa de Agua Potable "Virgen de las Nieves"
 */

// Zona horaria
date_default_timezone_set('America/La_Paz');

// Información de la aplicación
define('APP_NAME', 'Sistema de Gestión - Cooperativa de Agua');
define('APP_VERSION', '1.2.0');

// Rutas base
define('BASE_PATH', dirname(__DIR__));
define('BASE_URL', '/agua');

// Configuración de sesión
define('SESSION_NAME', 'cooperativa_agua_session');
define('SESSION_LIFETIME', 3600 * 8); // 8 horas

// Meses en español
$GLOBALS['meses'] = [
    '01' => 'Enero',
    '02' => 'Febrero',
    '03' => 'Marzo',
    '04' => 'Abril',
    '05' => 'Mayo',
    '06' => 'Junio',
    '07' => 'Julio',
    '08' => 'Agosto',
    '09' => 'Septiembre',
    '10' => 'Octubre',
    '11' => 'Noviembre',
    '12' => 'Diciembre'
];

/**
 * Obtener configuración de la cooperativa
 */
function getConfig() {
    static $config = null;
    if ($config === null) {
        require_once BASE_PATH . '/config/database.php';
        $config = fetchOne("SELECT * FROM configuracion LIMIT 1");
    }
    return $config;
}

/**
 * Formatear monto en Bolivianos
 */
function formatMoney($amount) {
    return 'Bs. ' . number_format($amount, 2, ',', '.');
}

/**
 * Formatear fecha
 */
function formatDate($date, $format = 'd/m/Y') {
    if (empty($date)) return '-';
    return date($format, strtotime($date));
}

/**
 * Formatear periodo (2024-01 -> Enero 2024)
 */
function formatPeriodo($periodo) {
    if (empty($periodo)) return '-';
    $parts = explode('-', $periodo);
    if (count($parts) != 2) return $periodo;
    $mes = $GLOBALS['meses'][$parts[1]] ?? $parts[1];
    return $mes . ' ' . $parts[0];
}

/**
 * Sanitizar entrada
 */
function sanitize($input) {
    if (is_array($input)) {
        return array_map('sanitize', $input);
    }
    return htmlspecialchars(trim($input), ENT_QUOTES, 'UTF-8');
}

/**
 * Redireccionar
 */
function redirect($url) {
    header("Location: " . BASE_URL . $url);
    exit;
}

/**
 * Mensaje flash
 */
function setFlash($type, $message) {
    $_SESSION['flash'] = ['type' => $type, 'message' => $message];
}

function getFlash() {
    if (isset($_SESSION['flash'])) {
        $flash = $_SESSION['flash'];
        unset($_SESSION['flash']);
        return $flash;
    }
    return null;
}

/**
 * Generar número de recibo correlativo
 */
function generarNumeroRecibo() {
    require_once BASE_PATH . '/config/database.php';
    $config = fetchOne("SELECT correlativo_recibo FROM configuracion LIMIT 1");
    $numero = str_pad($config['correlativo_recibo'], 6, '0', STR_PAD_LEFT);
    update("UPDATE configuracion SET correlativo_recibo = correlativo_recibo + 1");
    return $numero;
}

/**
 * Verificar si es una petición AJAX
 */
function isAjax() {
    return isset($_SERVER['HTTP_X_REQUESTED_WITH']) &&
           strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest';
}

/**
 * Respuesta JSON
 */
function jsonResponse($data, $code = 200) {
    http_response_code($code);
    header('Content-Type: application/json');
    echo json_encode($data);
    exit;
}

